28	    /**
29	     * Get dominant colors from a screenshot using deterministic pixel sampling.
30	     * Ported from SpatialVisionEngine logic.
31	     */
32	    public async getDeterministicColors(imagePath: string): Promise<Result<Array<{ hex: string; count: number }>>> {
33	        const psScript = `
34	            [Reflection.Assembly]::LoadWithPartialName('System.Drawing') | Out-Null;
35	            $bmp = New-Object System.Drawing.Bitmap('${imagePath}');
36	            $colors = @{};
37	            # Sample a 50x50 grid to keep it fast
38	            for ($x=0; $x -lt $bmp.Width; $x += [Math]::Max(1, [Math]::Floor($bmp.Width/50))) {
39	                for ($y=0; $y -lt $bmp.Height; $y += [Math]::Max(1, [Math]::Floor($bmp.Height/50))) {
40	                    $p = $bmp.GetPixel($x, $y);
41	                    $hex = '#{0:X2}{1:X2}{2:X2}' -f $p.R, $p.G, $p.B;
42	                    $colors[$hex]++;
43	                }
44	            }
45	            $bmp.Dispose();
46	            $colors.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 10 | ForEach-Object {
47	                Write-Host ("{0}:{1}" -f $_.Key, $_.Value)
48	            }
49	        `.trim();
50	
51	        try {
52	            const { stdout } = await execAsync(`powershell -NoProfile -Command "${psScript.replace(/"/g, '\\"')}"`);
53	            const lines = stdout.split('\n').filter(l => l.includes(':'));
54	            const colors = lines.map(l => {
55	                const [hex, count] = l.trim().split(':');
56	                return { hex: hex!, count: parseInt(count!) };
57	            });
58	            return { ok: true, value: colors };
59	        } catch (err) {
60	            logger.error({ err }, 'Deterministic color detection failed');
61	            return { ok: false, error: err as Error };
62	        }
63	    }
