12	/**
13	 * Mutation Tier â€” Controls what level of change is permitted.
14	 *   Tier 1: Scalar â€” colors, numbers, booleans, short strings (SAFE, auto-approved)
15	 *   Tier 2: Structural â€” functions, arrays, objects (CONTROLLED, logged)
16	 *   Tier 3: FileRewrite â€” full file replacement (LOCKED, requires explicit flag)
17	 */
18	export const enum MutationTier {
19	    Scalar = 1,
20	    Structural = 2,
21	    FileRewrite = 3
22	}
23	
24	/** Allowed AST node kinds for Tier 1 (Scalar) mutations */
25	const SCALAR_KINDS = new Set([
26	    'StringLiteral',
27	    'NumericLiteral',
28	    'TrueKeyword',
29	    'FalseKeyword',
30	    'NoSubstitutionTemplateLiteral'
31	]);
32	
33	/** Allowed AST node kinds for Tier 2 (Structural) mutations */
34	const STRUCTURAL_KINDS = new Set([
35	    ...SCALAR_KINDS,
36	    'ArrayLiteralExpression',
37	    'ObjectLiteralExpression',
38	    'ArrowFunction',
39	    'CallExpression'
40	]);
