42	/**
43	 * Validate that a payload is safe to inject as a scalar initializer.
44	 * Rejects multi-line payloads, imports, exports, class definitions â€” 
45	 * anything that would turn a value slot into a program.
46	 */
47	function isSafeScalarPayload(value: string): { safe: boolean; reason?: string } {
48	    if (value.length > 200) {
49	        return { safe: false, reason: `Payload too large (${value.length} chars, max 200)` };
50	    }
51	    if (value.includes('\n') || value.includes('\r')) {
52	        return { safe: false, reason: 'Payload contains newlines â€” not a scalar value' };
53	    }
54	    if (/\b(import|export|class|function\s+\w+|interface|type\s+\w+)\b/.test(value)) {
55	        return { safe: false, reason: 'Payload contains structural keywords (import/export/class/function) â€” not a scalar' };
56	    }
57	    if (value.includes('```')) {
58	        return { safe: false, reason: 'Payload contains markdown code fences â€” likely raw AI output, not a value' };
59	    }
60	    return { safe: true };
61	}
62	
63	/**
64	 * Detect the mutation tier required for a given AST node kind.
65	 */
66	function detectMutationTier(kindName: string): MutationTier {
67	    if (SCALAR_KINDS.has(kindName)) return MutationTier.Scalar;
68	    if (STRUCTURAL_KINDS.has(kindName)) return MutationTier.Structural;
69	    return MutationTier.FileRewrite;
70	}
