72	/**
73	 * Extract a clean hex color from potentially noisy AI output.
74	 * Returns null if no valid hex color is found.
75	 */
76	function extractHexColor(input: string): string | null {
77	    // Strip markdown
78	    let clean = input;
79	    if (clean.includes('```')) {
80	        const matches = clean.match(/```(?:typescript|glsl|javascript|css)?([\s\S]*?)```/);
81	        clean = matches ? matches[1]!.trim() : clean.replace(/```[a-z]*\n?/gi, '').replace(/```/g, '').trim();
82	    }
83	
84	    // Match hex color patterns
85	    const hexMatch = clean.match(/#([0-9a-fA-F]{3,8})\b/);
86	    if (hexMatch) return hexMatch[0];
87	
88	    // Match bare 6-digit hex (without #)
89	    const bareHex = clean.match(/^([0-9a-fA-F]{6})$/);
90	    if (bareHex) return `#${bareHex[1]}`;
91	
92	    // If the cleaned value IS just a short string that looks like a color name, allow it
93	    if (/^[a-zA-Z]{3,20}$/.test(clean.trim()) && clean.trim().length < 30) {
94	        return clean.trim(); // CSS named color like 'crimson', 'azure'
95	    }
96	
97	    return null;
98	}
