102	/**
103	 * Resolve `tsconfig.json` from the package root using `import.meta.url`,
104	 * NOT from `process.cwd()`. This ensures the ShaderInjector works
105	 * regardless of where the CLI was invoked from.
106	 */
107	function resolveProjectTsConfig(): string {
108	    try {
109	        // Walk from this file (dist/vision/ShaderInjector.js or src/vision/ShaderInjector.ts)
110	        // up to the project root where tsconfig.json lives.
111	        const thisFile = fileURLToPath(import.meta.url);
112	        const projectRoot = path.resolve(path.dirname(thisFile), '..', '..');
113	        const tsconfigPath = path.join(projectRoot, 'tsconfig.json');
114	
115	        if (existsSync(tsconfigPath)) {
116	            return tsconfigPath;
117	        }
118	    } catch {
119	        // Fallback below
120	    }
121	
122	    // Fallback: try CWD (works when run from project root)
123	    const cwdPath = path.resolve('./tsconfig.json');
124	    if (existsSync(cwdPath)) {
125	        return cwdPath;
126	    }
127	
128	    // Ultimate fallback: skip tsconfig entirely (ts-morph will use defaults)
129	    logger.warn('tsconfig.json not found via import.meta.url or CWD. Using ts-morph defaults.');
130	    return '';
131	}
