135	/**
136	 * ShaderInjector â€” AST-safe mutation engine for 3D materials.
137	 * Uses ts-morph to safely modify shaders and procedural textures.
138	 * 
139	 * Mutation Contract:
140	 *   - Tier 1 (Scalar): Auto-approved. Colors, numbers, flags.
141	 *   - Tier 2 (Structural): Logged, requires explicit opt-in.
142	 *   - Tier 3 (FileRewrite): BLOCKED unless `allowFileRewrite` is true.
143	 *   
144	 * All mutations validate payload safety BEFORE touching the AST.
145	 * Backup is created BEFORE mutation. Rollback on any compile error.
146	 */
147	export class ShaderInjector {
148	    private project: Project;
149	
150	    constructor() {
151	        const tsconfigPath = resolveProjectTsConfig();
152	
153	        this.project = new Project({
154	            ...(tsconfigPath ? { tsConfigFilePath: tsconfigPath } : {}),
155	            skipAddingFilesFromTsConfig: true
156	        });
157	    }
158	
159	    /**
160	     * Inject a color modification into a procedural texture file.
161	     * Finds VariableDeclarations with names like 'DEFAULT_COLOR' or 'PRIMARY_COLOR'
162	     * and mutates their initializer â€” but ONLY if the mutation is safe.
163	     * 
164	     * Mutation Contract enforced:
165	     *   1. Extracts a clean hex color from the payload (rejects raw AI output)
166	     *   2. Validates initiator kind is Scalar (StringLiteral, NumericLiteral)
167	     *   3. Validates payload size and content (no imports, no classes, no newlines)
168	     *   4. Creates a backup before mutation
169	     *   5. Restores backup if ts-morph throws during save
170	     */
171	    public async injectColor(filePath: string, hexCode: string): Promise<Result<ActuationResult>> {
172	        logger.info({ filePath, hexCode: hexCode.substring(0, 50) }, 'Engaging AST injection for color mutation');
173	
174	        // â•â•â• STEP 1: Intent Alignment â€” Extract the actual color value â•â•â•
175	        const cleanColor = extractHexColor(hexCode);
176	        if (!cleanColor) {
177	            const reason = `Payload is not a recognizable color value. Got: "${hexCode.substring(0, 80)}..."`;
178	            logger.error({ hexCode: hexCode.substring(0, 100) }, reason);
179	            return { ok: false, error: new Error(`MUTATION REJECTED (Intent Mismatch): ${reason}`) };
180	        }
181	
182	        // â•â•â• STEP 2: Payload Gate â€” Validate the cleaned value â•â•â•
183	        const safeCheck = isSafeScalarPayload(cleanColor);
184	        if (!safeCheck.safe) {
185	            logger.error({ cleanColor, reason: safeCheck.reason }, 'MUTATION REJECTED: Payload failed safety gate');
186	            return { ok: false, error: new Error(`MUTATION REJECTED (Payload Gate): ${safeCheck.reason}`) };
187	        }
188	
189	        // â•â•â• STEP 3: Backup â€” Create pre-mutation snapshot â•â•â•
190	        const backupPath = `${filePath}.pog2-backup`;
191	        try {
192	            if (existsSync(filePath)) {
193	                copyFileSync(filePath, backupPath);
194	                logger.info({ backupPath }, 'Pre-mutation backup created');
195	            }
196	        } catch (backupErr) {
197	            logger.warn({ err: backupErr }, 'Failed to create backup (proceeding with caution)');
198	        }
199	
200	        try {
201	            const sourceFile = this.project.addSourceFileAtPath(filePath);
202	
203	            // Look for color constants
204	            const varDecls = sourceFile.getVariableDeclarations();
205	            let mutated = false;
206	            const mutationLog: string[] = [];
207	
208	            for (const decl of varDecls) {
209	                const name = decl.getName();
210	                if (name.includes('COLOR') || name.includes('STYLE')) {
211	
212	                    // â•â•â• STEP 4: Type-Locked Mutation â€” Check initializer kind â•â•â•
213	                    const initKind = decl.getInitializer()?.getKindName() || 'NoInitializer';
214	                    const requiredTier = detectMutationTier(initKind);
215	
216	                    if (requiredTier > MutationTier.Scalar) {
217	                        logger.warn({
218	                            variable: name,
219	                            kindName: initKind,
220	                            tier: requiredTier
221	                        }, `Skipping variable: initializer kind "${initKind}" requires Tier ${requiredTier} (only Tier 1 Scalar allowed)`);
222	                        mutationLog.push(`SKIP: ${name} (kind: ${initKind}, tier: ${requiredTier})`);
223	                        continue;
224	                    }
225	
226	                    // â•â•â• STEP 5: Safe Mutation â€” Replace scalar value â•â•â•
227	                    const oldValue = decl.getInitializer()?.getText() || 'undefined';
228	                    decl.setInitializer(`'${cleanColor}'`);
229	                    mutated = true;
230	                    mutationLog.push(`MUTATED: ${name} = '${cleanColor}' (was: ${oldValue})`);
231	
232	                    logger.info({
233	                        variable: name,
234	                        oldValue,
235	                        newValue: cleanColor,
236	                        kind: initKind
237	                    }, 'Scalar mutation applied');
238	                }
239	            }
240	
241	            if (!mutated) {
242	                logger.warn({ filePath, mutations: mutationLog }, 'No eligible color constants found for scalar mutation.');
243	                // Don't append raw comments â€” clean rejection
244	                return {
245	                    ok: true,
246	                    value: {
247	                        success: false,
248	                        details: `No eligible COLOR/STYLE constants found in ${path.basename(filePath)}. ` +
249	                            (mutationLog.length > 0 ? `Skipped: ${mutationLog.join('; ')}` : 'File contains no matching declarations.')
250	                    }
251	                };
252	            }
253	
254	            await sourceFile.save();
255	
256	            // â•â•â• STEP 6: Post-Mutation Verification â•â•â•
257	            // If the saved file has syntax errors, rollback
258	            const diagnostics = sourceFile.getPreEmitDiagnostics();
259	            const hasErrors = diagnostics.some(d => d.getCategory() === 0); // 0 = Error
260	
261	            if (hasErrors) {
262	                logger.error({ diagnostics: diagnostics.length }, 'POST-MUTATION COMPILE ERRORS DETECTED. Rolling back.');
263	                this.rollbackFromBackup(filePath, backupPath);
264	                return {
265	                    ok: false,
266	                    error: new Error(`MUTATION ROLLBACK: Post-mutation compile errors detected (${diagnostics.length} issues). Backup restored.`)
267	                };
268	            }
269	
270	            return {
271	                ok: true,
272	                value: {
273	                    success: true,
274	                    details: `Injected ${cleanColor} into ${path.basename(filePath)} via AST. Mutations: ${mutationLog.join('; ')}`
275	                }
276	            };
277	        } catch (err) {
278	            // â•â•â• EMERGENCY ROLLBACK â•â•â•
279	            logger.error({ err }, 'AST Injection failed â€” attempting rollback');
280	            this.rollbackFromBackup(filePath, backupPath);
281	            return { ok: false, error: err as Error };
282	        }
283	    }
284	
285	    /**
286	     * Restore a file from its pre-mutation backup.
287	     */
288	    private rollbackFromBackup(filePath: string, backupPath: string): void {
289	        try {
290	            if (existsSync(backupPath)) {
291	                copyFileSync(backupPath, filePath);
292	                logger.info({ filePath, backupPath }, 'ðŸ”„ Rollback complete â€” backup restored.');
293	            } else {
294	                logger.error({ filePath }, 'ROLLBACK FAILED: No backup file found.');
295	            }
296	        } catch (err) {
297	            logger.error({ err, filePath }, 'ROLLBACK FAILED: Could not restore backup.');
298	        }
299	    }
300	
301	    /**
302	     * Revert a file from its `.pog2-backup`.
303	     */
304	    public async revert(filePath: string): Promise<Result<ActuationResult>> {
305	        const backupPath = `${filePath}.pog2-backup`;
306	
307	        if (!existsSync(backupPath)) {
308	            logger.warn({ filePath }, 'No backup found to revert from.');
309	            return { ok: false, error: new Error(`No .pog2-backup file found for ${filePath}`) };
310	        }
311	
312	        try {
313	            copyFileSync(backupPath, filePath);
314	            logger.info({ filePath }, 'ðŸ”„ File reverted to pre-mutation state.');
315	            return { ok: true, value: { success: true, details: `Reverted ${path.basename(filePath)} from backup` } };
316	        } catch (err) {
317	            logger.error({ err }, 'Revert failed');
318	            return { ok: false, error: err as Error };
319	        }
320	    }
321	}
