166	    /**
167	     * Delete temporary render and analysis artifacts.
168	     */
169	    private async cleanup() {
170	        const files = ['model.png', 'model.glb', 'pedagogy_profile.json', 'wiki_context.json'];
171	        for (const file of files) {
172	            try {
173	                await fs.unlink(join(process.cwd(), file));
174	            } catch (e) {
175	                // Ignore missing files
176	            }
177	        }
178	    }
179	}
