127	    public async confirm(message: string): Promise<boolean> {
128	        let isTemp = false;
129	        if (!this.rl) {
130	            this.rl = readline.createInterface({
131	                input: process.stdin,
132	                output: process.stdout
133	            });
134	            isTemp = true;
