15	export class ClinicalLogger {
16	    private readonly logDir: string;
17	    private readonly logPath: string;
18	    private readonly MAX_LOG_SIZE = 100 * 1024 * 1024; // 100MB
19	
20	    constructor(projectRoot: string) {
21	        this.logDir = join(projectRoot, 'logs');
22	        this.logPath = join(this.logDir, 'neurological_audit.log');
23	        this.ensureLogFile();
