26	    private ensureLogFile(): void {
27	        if (!existsSync(this.logDir)) {
28	            mkdirSync(this.logDir, { recursive: true });
29	        }
30	
31	        if (existsSync(this.logPath)) {
32	            const stats = statSync(this.logPath);
33	            if (stats.size >= this.MAX_LOG_SIZE) {
34	                const archivePath = join(this.logDir, `neurological_audit_${Date.now()}.log`);
35	                renameSync(this.logPath, archivePath);
36	            }
37	        }
38	    }
