196	    private async executeWin32<T>(name: string, operation: () => Promise<T>): Promise<DiagnosticResult<T>> {
197	        let attempts = 0;
198	        const maxAttempts = 3;
199	        const backoff = [100, 500, 2000];
200	
201	        while (attempts < maxAttempts) {
202	            try {
203	                const result = await operation();
204	                this.clinicalLogger.log('INFO', name, 'WIN32_OPERATION_SUCCESS');
205	                return { success: true, data: result, timestamp: new Date() };
206	            } catch (err: any) {
207	                attempts++;
208	                this.clinicalLogger.log('WARN', name, 'WIN32_OPERATION_FAILED', { attempt: attempts }, { code: err?.code || 'RUN_ERR', message: err?.message || 'Unknown', command: name });
209	                if (attempts >= maxAttempts) {
210	                    this.clinicalLogger.log('ERROR', name, 'WIN32_CIRCUIT_BREAKER', { attempts }, { code: 'CIRCUIT_BREAKER', message: 'Max retries exceeded' });
211	                    return { success: false, error: { code: 'WIN32_EXHAUSTED', message: err?.message || 'Exhausted retries', command: name }, timestamp: new Date() };
212	                }
213	                await new Promise(resolve => setTimeout(resolve, backoff[attempts - 1]));
214	            }
215	        }
216	        return { success: false, error: { code: 'UNKNOWN_STATE', message: 'Failed to execute', command: name }, timestamp: new Date() };
217	    }
