219	    private runShell(cmd: string, args: string[]): Promise<string> {
220	        return new Promise((resolve, reject) => {
221	            const child: ChildProcess = spawn(cmd, args, { cwd: this.projectRoot });
222	            this.activeProcesses.add(child);
223	            let output = '';
224	            let errorOutput = '';
225	
226	            child.stdout?.on('data', (data) => { output += data.toString(); });
227	            child.stderr?.on('data', (data) => { errorOutput += data.toString(); });
228	
229	            child.on('close', (code) => {
230	                this.activeProcesses.delete(child);
231	                if (code === 0) resolve(output);
232	                else reject(new Error(`Exit ${code}: ${errorOutput}`));
233	            });
234	            child.on('error', (err) => {
235	                this.activeProcesses.delete(child);
236	                reject(err);
237	            });
238	        });
239	    }
