241	    public async checkDiskHealth(): Promise<DiagnosticResult<DiskSubstrate>> {
242	        return this.executeWin32('checkDiskHealth', async () => {
243	            const root = hasSovereignDrive() ? getSovereignRoot() : process.cwd().split(':')[0] + ':';
244	            const driveLetter = root.split(':')[0] || 'C';
245	            const psScript = `Get-WmiObject -Class Win32_LogicalDisk | Where-Object DeviceID -eq '${driveLetter}:' | Select-Object Size,FreeSpace,VolumeName | ConvertTo-Json -Compress`;
246	            const output = await this.runShell('powershell.exe', ['-NoProfile', '-Command', psScript]);
247	
248	            const jsonStart = output.indexOf('{');
249	            if (jsonStart === -1) throw new Error('No JSON object found in output');
250	
251	            const data = JSON.parse(output.substring(jsonStart));
252	            const size = BigInt(data.Size || 0);
253	            const free = BigInt(data.FreeSpace || 0);
254	
255	            let healthStats: 'HEALTHY' | 'DEGRADED' | 'CRITICAL' = 'HEALTHY';
256	            if (size > 0n) {
257	                const usedPercent = Number((size - free) * 100n / size);
258	                if (usedPercent >= 95) healthStats = 'CRITICAL';
259	                else if (usedPercent >= 85) healthStats = 'DEGRADED';
260	            }
261	
262	            return {
263	                totalBytes: size,
264	                freeBytes: free,
265	                volumeLabel: data.VolumeName || '',
266	                healthStatus: healthStats
267	            } as DiskSubstrate;
268	        });
269	    }
