3	/**
4	 * The OpenTelemetry / Distributed AI Envelope Event Standard.
5	 * Standardizes event tracing (traceId, spanId) and ordering across the entire runtime.
6	 */
7	export interface SovereignEvent<T = any> {
8	    id: string;          // uuidv7 time-sorted identifier
9	    type: string;        // E.g., 'interaction', 'decision', 'vision.analysis'
10	    timestamp: number;   // Unix epoch
11	    source: string;      // The component that fired the event (e.g., TernaryRouter)
12	    traceId?: string;    // Binds events together across a single cognitive pipeline execution
13	    spanId?: string;     // Secondary grouping (e.g., trial #4 within an experiment)
14	    sequence?: number;   // Incremental ordering within a trace
15	    fidelity?: number;   // Cognitive Fidelity Level (LearningFidelity)
16	    payload: T;          // The actual data payload
17	    meta?: Record<string, any>; // Arbitrary context (model versions, hardware constraints)
18	}
19	
20	// Event Handler Definition
21	type EventHandler = (event: SovereignEvent) => void;
22	
23	/**
24	 * EventBus - The non-blocking backbone of the Phase 14.5 architecture.
25	 * Decouples synchronous disk storage from the `TaskScheduler`.
26	 */
27	export class EventBus {
28	    private static instance: EventBus;
29	    private handlers = new Map<string, EventHandler[]>();
30	    private globalHandlers: EventHandler[] = [];
31	
32	    private constructor() { }
33	
34	    public static getInstance(): EventBus {
35	        if (!EventBus.instance) {
36	            EventBus.instance = new EventBus();
37	        }
38	        return EventBus.instance;
39	    }
40	
41	    private queueHandler?: (op: () => void) => void;
42	
43	    public setQueueHandler(handler: (op: () => void) => void) {
44	        this.queueHandler = handler;
45	    }
46	
47	    private defer(op: () => void) {
48	        if (this.queueHandler) {
49	            this.queueHandler(op);
50	        } else {
51	            setImmediate(op);
52	        }
53	    }
54	
55	    /**
56	     * Pushes an event to the bus. 
57	     * Uses the injected deterministic queue handler (CNSGodheadPulseVolley) 
58	     * or falls back to Node's `setImmediate`.
59	     */
60	    public publish(event: Omit<SovereignEvent, 'id' | 'timestamp'> & { id?: string, timestamp?: number, fidelity?: number }): string {
61	        const fullEvent: SovereignEvent = {
62	            ...event,
63	            id: event.id || uuidv7(),
64	            timestamp: event.timestamp || Date.now(),
65	            fidelity: event.fidelity
66	        };
67	
68	        const subs = this.handlers.get(fullEvent.type) || [];
69	        for (const handler of subs) {
70	            this.defer(() => handler(fullEvent));
71	        }
72	
73	        // Dispatch to universal listeners (like GlobeStateLimb)
74	        for (const handler of this.globalHandlers) {
75	            this.defer(() => handler(fullEvent));
76	        }
77	
78	        return fullEvent.id;
79	    }
80	
81	    /**
82	     * Subscribes a processor to all event types.
83	     */
84	    public subscribeAll(handler: EventHandler): void {
85	        this.globalHandlers.push(handler);
86	    }
87	
88	    /**
89	     * Subscribes a processor to a specific event type.
90	     */
91	    public subscribe(type: string, handler: EventHandler): void {
92	        if (!this.handlers.has(type)) {
93	            this.handlers.set(type, []);
94	        }
95	        this.handlers.get(type)!.push(handler);
96	    }
97	}
