33	    dimensions: { width: number; height: number; plane: number };
34	    mapsquare: string;             // "50,50"
35	    timestamp: number;
36	}
37	
38	export interface CollisionSnapshot {
39	    mapsquare: string;
40	    plane: number;
41	    blocked: number[];             // Packed coords (x << 14 | y)
42	    walkable: number[];
43	}
44	
45	export interface WorldTelemetryFrame {
46	    tick: number;
47	    timestamp: number;
48	    hexagramState: {
49	        activeId: number;
50	        definition: HexagramDefinition;
51	        engineFocus: string[];
52	        yaoLines: boolean[];        // 6 lines, true = yang/active
53	    };
54	    ghostSplat: GhostSplatSnapshot | null;
55	    collisionGrid: CollisionSnapshot[];
56	    activeEntities: {
57	        npcs: number;
58	        items: number;
59	        objects: number;
60	        players: number;
61	    };
62	}
63	
64	/**
65	 * POG2WorldDO — Telemetry Radiator & State Broadcaster
66	 *
67	 * This Durable Object does NOT own any engines. It pulls state from engine
68	 * singletons or sibling DO stubs and broadcasts WorldTelemetryFrames to
69	 * WebSocket subscribers on a 300ms cycle aligned with RS3 client prediction.
70	 *
71	 * Endpoints:
72	 *   GET /health    → { status, tick }
73	 *   GET /telemetry → Current WorldTelemetryFrame as JSON
74	 *   GET /ws        → WebSocket upgrade (channel subscription)
75	 */
76	export class POG2WorldDO extends DurableObjectBase {
77	    private tick: number = 0;
78	    private clients: Set<WebSocket> = new Set();
79	    private telemetryInterval: ReturnType<typeof setInterval> | null = null;
80	
81	    constructor(state: DurableObjectStateAmbient, env: any) {
82	        super(state, env);
83	        this.startTelemetryLoop();
84	    }
85	
86	    async fetch(request: Request): Promise<Response> {
87	        const url = new URL(request.url);
88	
89	        if (url.pathname === '/health') {
90	            return new Response(JSON.stringify({ status: 'alive', tick: this.tick }), {
91	                status: 200,
92	                headers: { 'Content-Type': 'application/json' }
93	            });
94	        }
95	
96	        if (url.pathname === '/ws') {
97	            const pair = new WebSocketPairAmbient();
98	            const [client, server] = [pair[0], pair[1]];
99	            this.handleConnection(server);
100	            return new Response(null, { status: 101, webSocket: client } as any);
101	        }
102	
103	        if (url.pathname === '/telemetry') {
104	            return new Response(JSON.stringify(this.buildFrame()), {
105	                headers: { 'Content-Type': 'application/json' }
106	            });
107	        }
108	
109	        return new Response('Not Found', { status: 404 });
110	    }
111	
112	    private handleConnection(ws: WebSocket): void {
113	        (ws as any).accept?.();
114	        this.clients.add(ws);
115	
116	        // Immediate push of current state
117	        ws.send(JSON.stringify({ type: 'INIT', frame: this.buildFrame() }));
118	
119	        ws.addEventListener('message', (msg: MessageEvent) => {
120	            try {
121	                const data = JSON.parse(typeof msg.data === 'string' ? msg.data : '{}');
122	                if (data.type === 'SUBSCRIBE') {
123	                    // Channel filtering: 'hexagram', 'ghostsplat', 'collision', 'all'
124	                    (ws as any).__channels = data.channels || ['all'];
125	                }
126	            } catch {
127	                // Malformed message — ignore
128	            }
129	        });
130	
131	        ws.addEventListener('close', () => this.clients.delete(ws));
132	    }
133	
134	    private startTelemetryLoop(): void {
135	        // 300ms cycle — aligns with RS3 client prediction layer
136	        this.telemetryInterval = setInterval(() => {
137	            this.tick++;
138	            const frame = this.buildFrame();
139	            this.broadcast(frame);
140	        }, 300);
141	    }
142	
143	    private buildFrame(): WorldTelemetryFrame {
144	        return {
145	            tick: this.tick,
146	            timestamp: Date.now(),
147	            hexagramState: this.getHexagramState(),
148	            ghostSplat: this.getGhostSplatSnapshot(),
149	            collisionGrid: this.getCollisionSnapshot(),
150	            activeEntities: this.getEntityCounts()
151	        };
152	    }
153	
154	    private getHexagramState(): WorldTelemetryFrame['hexagramState'] {
155	        // Resolved from HexagramManager via globalThis (same isolate)
156	        // or via DO-stub call (cross-isolate)
157	        const activeHex = (globalThis as any).HEXAGRAM_MANAGER?.getActiveHexagram()
158	            || { id: 1, binary: '111111', name: 'The Creative', gameplay: { engineFocus: [] } };
159	        return {
160	            activeId: activeHex.id,
161	            definition: activeHex,
162	            engineFocus: activeHex.gameplay?.engineFocus || [],
163	            yaoLines: activeHex.binary.split('').map((b: string) => b === '1')
164	        };
165	    }
166	
167	    private getGhostSplatSnapshot(): GhostSplatSnapshot | null {
168	        // GhostSplatEngine exports density matrix via globalThis
169	        return (globalThis as any).GHOST_SPLAT?.getSnapshot() || null;
170	    }
171	
172	    private getCollisionSnapshot(): CollisionSnapshot[] {
173	        // SovereignCollisionEngine heatmap for current mapsquare
174	        return (globalThis as any).COLLISION_ENGINE?.getBlockedCoords() || [];
175	    }
176	
177	    private getEntityCounts(): WorldTelemetryFrame['activeEntities'] {
178	        // From WorldStateLimb or SimulationHarness
179	        const state = (globalThis as any).GAME_STATE;
180	        if (state) {
181	            return {
182	                npcs: state.npcMap?.size || 0,
183	                items: state.groundItems?.size || 0,
184	                objects: state.objectMap?.size || 0,
185	                players: state.players?.size || 0
186	            };
187	        }
188	        return { npcs: 0, items: 0, objects: 0, players: 0 };
189	    }
190	
191	    private broadcast(frame: WorldTelemetryFrame): void {
192	        const msg = JSON.stringify({ type: 'TICK', frame });
193	        for (const ws of this.clients) {
194	            try {
195	                const channels: string[] = (ws as any).__channels || ['all'];
196	                if (channels.includes('all') || channels.includes('telemetry')) {
197	                    ws.send(msg);
198	                }
199	            } catch {
200	                // Dead socket — will be cleaned on 'close' event
201	                this.clients.delete(ws);
202	            }
203	        }
204	    }
205	}
